parameters.query:
select
  public.get_anthropic_key() as anthropic_key,
  (select agent_id from public.agent_routing where active = true and model_id = 'claude-haiku-4-5' limit 1) as agent_id,
  (select value from public.config where key = 'managed_agent_environment_id') as environment_id,
  (select vault_id from public.user_data_and_config where clickup_user_id = '2521617' and status = 'active' and vault_id is not null limit 1) as vault_id;

parameters.jsCode:
const inp = $input.first().json || {};
const key = (inp.anthropic_key || '').toString().trim();
const agent = (inp.agent_id || '').toString().trim();
const env = (inp.environment_id || '').toString().trim();
const vault = (inp.vault_id || '').toString().trim();
if (!key || !agent || !env || !vault) {
  throw new Error('Brak wymaganych danych sondy (nie mozna wykonac testu): ' + JSON.stringify({ hasKey: !!key, agent: agent || null, env: env || null, hasVault: !!vault }));
}
const API = 'https://api.anthropic.com';
const H = { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'managed-agents-2026-04-01,files-api-2025-04-14', 'content-type': 'application/json' };
const t0 = Date.now();
// 1) create the probe session with the ClickUp vault attached
const sess = await this.helpers.httpRequest({ method: 'POST', url: API + '/v1/sessions', headers: H, body: { agent: agent, environment_id: env, vault_ids: [vault] }, json: true, timeout: 30000 });
const sid = sess && sess.id;
if (!sid) throw new Error('Sonda: brak session id z /v1/sessions: ' + JSON.stringify(sess).slice(0, 200));
// 2) ask the agent to call ONLY the hierarchy tool
await this.helpers.httpRequest({ method: 'POST', url: API + '/v1/sessions/' + sid + '/events', headers: H, json: true, timeout: 30000, body: { events: [{ type: 'user.message', content: [{ type: 'text', text: 'Test zdrowotny polaczenia z ClickUp. Wywolaj TERAZ narzedzie clickup_get_workspace_hierarchy i nic wiecej. NIE wywoluj zadnych innych narzedzi (ani get_task_details, ani deliver_output). Po wywolaniu odpowiedz jednym zdaniem.' }] }] } });
// 3) poll for a connectivity verdict
let connected = false; const denied = []; let clickupCustom = false; let sessErr = null;
for (let i = 0; i < 12; i++) {
  await new Promise(function (r) { setTimeout(r, 4000); });
  let ev;
  try { ev = await this.helpers.httpRequest({ method: 'GET', url: API + '/v1/sessions/' + sid + '/events?limit=100', headers: H, json: true, timeout: 30000 }); } catch (e) { continue; }
  const data = (ev && Array.isArray(ev.data)) ? ev.data : [];
  for (const e of data) {
    const nm = (e && typeof e.name === 'string') ? e.name : '';
    if (e.type === 'agent.mcp_tool_use' && nm.indexOf('clickup_') === 0) connected = true;
    if (e.type === 'agent.custom_tool_use' && nm.indexOf('clickup_') === 0) clickupCustom = true;
    if (e.type === 'agent.tool_result') { const t = Array.isArray(e.content) ? e.content.map(function (c) { return (c && c.text) || ''; }).join(' ') : ''; const m = t.match(/Permission to use (clickup_[A-Za-z0-9_]+) has been denied/); if (m) denied.push(m[1]); }
    if (e.type === 'session.error' || (typeof e.type === 'string' && e.type.indexOf('error') >= 0 && e.error)) sessErr = e.error || e;
  }
  if (connected || denied.length || clickupCustom || sessErr) break;
}
const elapsed = Math.round((Date.now() - t0) / 1000);
// best-effort cleanup (idle probe session otherwise lingers; harmless if DELETE is unsupported)
try { await this.helpers.httpRequest({ method: 'DELETE', url: API + '/v1/sessions/' + sid, headers: H, timeout: 15000 }); } catch (e) {}
if (connected) { return [{ json: { healthy: true, session_id: sid, elapsed_s: elapsed } }]; }
if (denied.length || clickupCustom || sessErr) {
  throw new Error('Sonda ClickUp MCP: narzedzie NIE polaczylo sie (' + elapsed + 's). denied=' + JSON.stringify(denied) + ' routedAsCustom=' + clickupCustom + ' sessionError=' + (sessErr ? JSON.stringify(sessErr).slice(0, 200) : 'brak') + ' session=' + sid);
}
// inconclusive: the agent did not attempt the tool within budget (steering miss, not an outage) -> do not alarm
return [{ json: { healthy: true, inconclusive: true, session_id: sid, elapsed_s: elapsed, note: 'Agent nie wywolal clickup_get_workspace_hierarchy w oknie sondy - wynik niejednoznaczny, brak alarmu.' } }];
